# System.Runtime.Intrinsics.X86.Avx512BW.VL — the mask-driven byte and word blends and masked
# loads and stores at 128 and 256 bits, the mask a vector's sign bits as in avx512f/blend.map.
target = avx512f,avx512bw,avx512dq,avx512vl
BlendVariable(v{W}{T},v{W}{T},v{W}{T}) @ref(Vector{W}.ConditionalSelect(Vector{W}.IsNegative($2.As<{cs}, {scs}>()).As<{scs}, {cs}>(), $1, $0)) = {mm}_mask_blend_epi{bits}({mm}_movepi{bits}_mask($2), $0, $1) for W in 128,256 for T in i8,u8,i16,u16
MaskLoad(p{T},v{W}{T},v{W}{T}) @ref(Vector{W}.ConditionalSelect(Vector{W}.IsNegative($1.As<{cs}, {scs}>()).As<{scs}, {cs}>(), Vector{W}.Load($0), $2)) = {mm}_mask_loadu_epi{bits}($2, {mm}_movepi{bits}_mask($1), (const void*)$0) for W in 128,256 for T in i8,u8,i16,u16
MaskStore(p{T},v{W}{T},v{W}{T}) = {mm}_mask_storeu_epi{bits}((void*)$0, {mm}_movepi{bits}_mask($1), $2) for W in 128,256 for T in i8,u8,i16,u16
